// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call sudicideAnyone() as owner (the contract's owner is the deployer, address(this) in setUp)
        // Use a different user for the second call
        address nonOwner = address(0x1234);

        // First call as owner (the deployer, which is this test contract in Foundry)
        vm.prank(address(this));
        c.sudicideAnyone();

        // Now try to call sudicideAnyone() again as non-owner; should revert if contract still exists
        bool callSucceeded;
        vm.prank(nonOwner);
        try c.sudicideAnyone() {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        // The reference (selfdestruct) destroys the contract, so the second call reverts (callSucceeded = false).
        // The buggy version (return) does not destroy, so the require fails (msg.sender != owner) -> revert as well.
        // Actually both revert for different reasons — but we need a divergence.
        // Let's instead check code.length after the first call:
        // (Already noted as tried; but we can check a different state: the contract address balance after a self-send?)
        // Actually, both revert on second call if sender is not owner, so no divergence there.
        // Let's try: after selfdestruct, the contract has no code, so any external call returns 0 bytes for a getter.
        // Check a public variable getter: smartfix_owner() should revert if contract gone.
        bool getterSucceeded;
        try c.smartfix_owner() {
            getterSucceeded = true;
        } catch {
            getterSucceeded = false;
        }

        // For reference (selfdestruct), getter reverts because contract destroyed => getterSucceeded = false.
        // For buggy, getter returns the owner address => getterSucceeded = true.
        assertTrue(!getterSucceeded, "Bug: contract still has code after sudicideAnyone call by owner");
    }
}

