pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);
        // Owner calls sudicideAnyone()
        address owner = address(this);
        vm.prank(owner);
        c.sudicideAnyone();
        // After call, check balance: reference selfdestructs (balance = 0), buggy keeps balance (1 ether)
        assertTrue(address(c).balance == 0, "Contract should have zero balance after selfdestruct");
    }
}
